spriteScript:
@tool
extends Sprite2D

@export_file("*.png") var image_path: String = "":
	set(value):
		image_path = value
		if is_inside_tree(): _load_pixels()

func _ready() -> void:
	_load_pixels()

func _load_pixels() -> void:
	if image_path.is_empty(): return
	var pixels := Image.load_from_file(image_path)
	if pixels == null or pixels.is_empty():
		push_error("SHOP_PART_LOAD_FAILED " + image_path)
		return
	texture = ImageTexture.create_from_image(pixels)
	centered = false
	texture_filter = CanvasItem.TEXTURE_FILTER_NEAREST

shopScript:
@tool
extends Node2D

@export var emitters_enabled := true:
	set(value):
		emitters_enabled = value
		if is_inside_tree(): _apply_visibility()
@export var props_enabled := true:
	set(value):
		props_enabled = value
		if is_inside_tree(): _apply_visibility()

func _ready() -> void:
	_apply_visibility()

func _apply_visibility() -> void:
	for part in get_children():
		if str(part.name).ends_with("emitter"): part.visible = emitters_enabled
		if str(part.name) in ["P07_chalkboard", "P08_large_planter", "P09_small_planter"]: part.visible = props_enabled
